export default definePlugin({
    name: "AutoTranslateNightcord",
    enabledByDefault: true,
    required: true,
    description: "Automatic translation for Nightcord.",
    authors: [{ name: "Flocord", id: 0n }],
    options: {
        autoTranslate: {
            description: "Automatically translate strings",
            type: 4, // select
            options: [
                { label: "English", value: "en", default: true },
                { label: "FranÃ§ais", value: "fr" },
                { label: "Ø§Ù„Ø¹Ø±Ø¨ÙŠØ©", value: "ar" },
                { label: "EspaÃ±ol", value: "es" },
                { label: "Ð ÑƒÑÑÐºÐ¸Ð¹", value: "ru" },
                { label: "ä¸­æ–‡", value: "zh" },
            ]
        },
    },
});

function normalizeLang(lang: string): SupportedLang {
    if (!lang) return "en";
    const l = lang.toLowerCase();
    if (l.startsWith("fr")) return "fr";
    if (l.startsWith("ar")) return "ar";
    if (l.startsWith("es")) return "es";
    if (l.startsWith("ru")) return "ru";
    if (l.startsWith("zh")) return "zh";
    return "en";
}

export function t(key: string): string {
    const rawLang = (Settings.language as string) ?? "en";
    const lang = normalizeLang(rawLang);
    if (lang === "en") return key;
    return translations[key]?.[lang] ?? translations[key]?.en ?? key;
}

export function useTranslation() {
    const rawLang = (Settings.language as string) ?? "en";
    const lang = normalizeLang(rawLang);
    return {
        t: (key: string) => {
            if (lang === "en") return key;
            return translations[key]?.[lang] ?? translations[key]?.en ?? key;
        },
        lang,
    };
}
